/** The footer both steppers share: where you are on the left, Back and Next on the right. */
function StepFooter({
	active,
	last,
	onChange,
	total,
}: {
	active: number
	last: string
	onChange: (step: number) => void
	total: number
}) {
	return (
		<Flex
			align="center"
			block
			gap="sm"
			justify="between"
		>
			<Typography
				size="sm"
				variant="muted"
			>
				Step {active + 1} of {total}
			</Typography>
			<Flex
				align="center"
				gap="sm"
			>
				<Button
					disabled={active === 0}
					onClick={() => onChange(active - 1)}
					variant="outline"
				>
					Back
				</Button>
				<Button onClick={() => onChange(Math.min(active + 1, total - 1))}>
					{active === total - 1 ? last : 'Next'}
				</Button>
			</Flex>
		</Flex>
	)
}

