/** One settings section: a form of its own, with its own save. */
function Section({
	children,
	description,
	id,
	title,
}: {
	children: React.ReactNode
	description: string
	id: string
	title: string
}) {
	return (
		<Form>
			<Card id={id}>
				<Card.Header bordered>
					<Card.Title headingLevel={2}>{title}</Card.Title>
					<Card.Description>{description}</Card.Description>
				</Card.Header>
				<Card.Content>
					<Flex
						align="stretch"
						direction="col"
						gap="md"
					>
						{children}
					</Flex>
				</Card.Content>
				<Card.Footer bordered>
					<Button
						size="sm"
						type="submit"
					>
						Save
					</Button>
				</Card.Footer>
			</Card>
		</Form>
	)
}

