function statusVariant(status: number): BadgeVariant {
	if (status >= 500) {
		return 'destructive'
	}

	if (status >= 400) {
		return 'warning'
	}

	return 'success'
}

const STATUS_TEXT: Record<number, string> = {
	200: 'OK',
	400: 'Bad request',
	402: 'Request failed',
	503: 'Unavailable',
}

const LOG_COLUMNS: TableColumns<LogEntry> = [
	{
		key: 'status',
		label: 'Status',
		selector: (row) => (
			<Badge
				size="sm"
				variant={statusVariant(row.status)}
			>
				{row.status} {STATUS_TEXT[row.status]}
			</Badge>
		),
		width: 150,
	},
	{
		key: 'request',
		label: 'Request',
		selector: (row) => (
			<Flex
				align="center"
				gap="xs"
			>
				<Badge
					size="sm"
					variant="outline"
				>
					{row.method}
				</Badge>
				<Typography
					size="sm"
					truncate
				>
					{row.path}
				</Typography>
			</Flex>
		),
		width: 320,
	},
	{
		key: 'source',
		label: 'Source',
		selector: (row) => (
			<Typography
				noWrap
				size="sm"
				variant="muted"
			>
				{row.source}
			</Typography>
		),
		width: 130,
	},
	{
		align: 'right',
		key: 'at',
		label: 'Time',
		selector: (row) => (
			<DateText
				format="HH:mm:ss"
				muted
				size="sm"
				value={row.at}
			/>
		),
		width: 90,
	},
]

