function SettingsHub() {
	return (
		<Layout.Content maxWidth="lg">
			<Page>
				<Page.Header
					description="Everything that configures this account, grouped by whose it is."
					title="Settings"
				/>
				<Page.Content>
					{HUB.map((group) => (
						<Flex
							align="stretch"
							direction="col"
							gap="sm"
							key={group.title}
						>
							<Typography
								component="h2"
								size="sm"
								weight="semibold"
							>
								{group.title}
							</Typography>
							<Grid
								cols={3}
								gap="md"
							>
								{group.links.map((link) => (
									<Card
										href={link.href}
										key={link.title}
										size="sm"
									>
										<Card.Header>
											<Flex
												align="center"
												gap="sm"
											>
												{link.icon}
												<Card.Title headingLevel={3}>{link.title}</Card.Title>
											</Flex>
											<Card.Description>{link.description}</Card.Description>
										</Card.Header>
									</Card>
								))}
							</Grid>
						</Flex>
					))}
				</Page.Content>
			</Page>
		</Layout.Content>
	)
}

