export function PaymentMethods({
	amount,
	errors,
	every,
	filled,
	headingLevel,
	method,
	onChange,
}: {
	amount: number
	errors?: boolean
	every: string
	filled?: boolean
	/** The level of the methods' headings; 3 under a section's h2, 2 right under the page's h1. */
	headingLevel?: 2 | 3
	method: Method
	onChange: (method: Method) => void
}) {
	return (
		<Accordion
			bordered
			headingLevel={headingLevel}
			indicator="radio"
			onChange={(next) => {
				if (next) {
					onChange(next as Method)
				}
			}}
			type="single"
			value={method}
		>
			<Accordion.Item value="pix">
				<Accordion.Trigger
					description="Autorize no app do banco — cobrança automática"
					rightSection={<QrCodeIcon size={18} />}
				>
					Pix Automático
				</Accordion.Trigger>
				<Accordion.Content>
					<PixFields
						amount={amount}
						every={every}
					/>
				</Accordion.Content>
			</Accordion.Item>
			<Accordion.Item value="card">
				<Accordion.Trigger
					description="Crédito, renovação automática"
					rightSection={<CreditCardIcon size={18} />}
				>
					Cartão
				</Accordion.Trigger>
				<Accordion.Content>
					<CardFields
						errors={errors}
						filled={filled}
					/>
				</Accordion.Content>
			</Accordion.Item>
			<Accordion.Item value="boleto">
				<Accordion.Trigger
					description="Confirma até 1 dia útil após o pagamento"
					rightSection={<ReceiptIcon size={18} />}
				>
					Boleto
				</Accordion.Trigger>
				<Accordion.Content>
					<BoletoFields />
				</Accordion.Content>
			</Accordion.Item>
		</Accordion>
	)
}

