type SignedInScenario = {
	left: 'upgrade' | 'downgrade' | 'interval' | 'purchase'
	payment: 'compact' | 'list' | 'new' | 'nothing-today'
	billing: 'compact' | 'full'
}

const SIGNED_IN_SCENARIOS: Record<string, SignedInScenario> = {
	'downgrade-scheduled': {
		billing: 'compact',
		left: 'downgrade',
		payment: 'nothing-today',
	},
	'interval-change': {
		billing: 'compact',
		left: 'interval',
		payment: 'compact',
	},
	'new-method': {
		billing: 'compact',
		left: 'purchase',
		payment: 'new',
	},
	'saved-billing': {
		billing: 'full',
		left: 'purchase',
		payment: 'compact',
	},
	'saved-method': {
		billing: 'compact',
		left: 'purchase',
		payment: 'list',
	},
	'upgrade-proration': {
		billing: 'compact',
		left: 'upgrade',
		payment: 'compact',
	},
}

